import{_ as d,o as r,c as a,a5 as e}from"./chunks/framework.R-FQ1xZ2.js";const m=JSON.parse('{"title":"L3 · RAG 检索增强","description":"","frontmatter":{},"headers":[],"relativePath":"kb/l3-rag/index.md","filePath":"kb/l3-rag/index.md","lastUpdated":null}'),n={name:"kb/l3-rag/index.md"};function o(g,t,s,h,l,i){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="l3-·-rag-检索增强" tabindex="-1">L3 · RAG 检索增强 <a class="header-anchor" href="#l3-·-rag-检索增强" aria-label="Permalink to &quot;L3 · RAG 检索增强&quot;">​</a></h1><blockquote><p>本层知识点导览 ｜ <strong>28 个知识点 / 10 页 / 101 学时</strong> ｜ 面试频率：高 9 页、中 1 页</p></blockquote><h2 id="这一层是什么" tabindex="-1">这一层是什么 <a class="header-anchor" href="#这一层是什么" aria-label="Permalink to &quot;这一层是什么&quot;">​</a></h2><p><strong>RAG（Retrieval-Augmented Generation，检索增强生成）</strong> 是把外部知识检索出来拼进上下文，再让模型基于这些材料回答。它是企业 AI 应用的第一个落点，也是 AI 岗位面试里考察最密集的领域——<strong>因为它是少数能同时考到「算法原理」（Embedding、ANN 索引、Cross-Encoder）与「工程落地」（解析、权限、护栏、延迟）的题目</strong>。</p><p>本层按<strong>一条完整链路的数据流</strong>组织：<strong>解析 → 切块 → 向量化 → 建索引 → 检索（稠密 + 稀疏）→ 融合 → 精排 → 改写/多跳 → 生成约束 → 引用与权限</strong>。它不是十个孤立专题，而是一条链上的十个环节——所以<strong>前一环的输出质量问题，后一环永远修不回来</strong>。</p><p>三句话概括这层的核心判断：</p><ol><li><strong>上游决定上限</strong>：解析与切块错了，向量化与精排再强也救不回来。</li><li><strong>召回与排序是两件事</strong>：混合检索修召回，Rerank 修排序，不能相互替代。</li><li><strong>没有普适最优参数</strong>：chunk size、top_k、HNSW 的 <code>M</code>/<code>efConstruction</code>、RRF 的 <code>k</code> 都必须在<strong>自己的语料与题集上做消融</strong>——这一层给的是<strong>判据</strong>，不是数字。</li></ol><h2 id="页面结构与学习顺序" tabindex="-1">页面结构与学习顺序 <a class="header-anchor" href="#页面结构与学习顺序" aria-label="Permalink to &quot;页面结构与学习顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>order</th><th>页面</th><th>覆盖知识点</th><th>频率</th><th>学时</th><th>依赖（先学什么）</th></tr></thead><tbody><tr><td>1</td><td><a href="./01-rag-fundamentals.html">① RAG 是什么，怎么搭最小闭环</a></td><td>L3-01 / 02 / 03</td><td>高</td><td>9</td><td>— （本层入口）</td></tr><tr><td>2</td><td><a href="./02-loading-and-parsing.html">② 文档加载与多格式解析</a></td><td>L3-04</td><td>高</td><td>5</td><td>先有 ① 的链路全图</td></tr><tr><td>3</td><td><a href="./03-chunking.html">③ 文本切块、参数与元数据</a></td><td>L3-05 / 06 / 07</td><td>高</td><td>11</td><td>依赖 ②（解析出的文本块是切块输入）</td></tr><tr><td>4</td><td><a href="./04-embedding.html">④ Embedding 原理、度量与选型</a></td><td>L3-08 / 09 / 10 / 11</td><td>高</td><td>14</td><td>依赖 ③（切块决定编码单元）</td></tr><tr><td>5</td><td><a href="./05-vector-index.html">⑤ 向量索引、库选型与 Top-k</a></td><td>L3-12 / 13 / 14 / 15</td><td>高</td><td>14</td><td>依赖 ④（有向量才谈索引）</td></tr><tr><td>6</td><td><a href="./06-sparse-and-hybrid.html">⑥ 稀疏检索与混合融合（BM25 + RRF）</a></td><td>L3-16 / 17</td><td>高</td><td>7</td><td>可与 ⑤ 并行；需先懂 ④ 的稠密路</td></tr><tr><td>7</td><td><a href="./07-rerank-and-query.html">⑦ Rerank、查询改写与多跳检索</a></td><td>L3-18 / 19 / 20 / 21</td><td>高</td><td>14</td><td>依赖 ⑥（精排的输入是融合后的候选集）</td></tr><tr><td>8</td><td><a href="./08-structured-and-graph.html">⑧ 结构化数据、图谱与多模态检索</a></td><td>L3-22 / 23 / 24</td><td>中</td><td>17</td><td>依赖 ⑦（路由/多跳是它的前置概念）</td></tr><tr><td>9</td><td><a href="./09-citations-and-security.html">⑨ 引用可溯源、权限与多租户隔离</a></td><td>L3-25 / 26</td><td>高</td><td>6</td><td>依赖 ③ 的元数据与 ⑦ 的候选结构</td></tr><tr><td>10</td><td><a href="./10-generation-and-agentic.html">⑩ 生成阶段约束与 Agentic RAG</a></td><td>L3-27 / 28</td><td>高</td><td>8</td><td><strong>最后一页</strong>：链路的收口，依赖 ⑦ 与 ⑨</td></tr></tbody></table><p><strong>读法建议</strong>：</p><ul><li><strong>第一遍（约 2 周，每天 2–3h）</strong>：按 1 → 2 → 3 → 4 → 5 → 6 → 7 顺序读，<strong>每页都回到自己的项目上对一遍</strong>。这条线是「一条能跑起来的链路」。</li><li><strong>第二遍（约 1 周）</strong>：读 8 → 9 → 10，这三页是<strong>企业级能力</strong>（结构化/图谱/多模态是能力扩展，引用与权限是能不能上线，生成约束与 Agentic 是收口）。</li><li><strong>面试前一天</strong>：只看每页的「面试怎么问」与「自检清单」，以及下面的<strong>最容易挂在哪</strong>。</li><li><strong>不要跳的顺序</strong>：③ → ④ → ⑤ 不能跳（切块→向量→索引是同一条数据流的接力）。⑥ 与 ⑤ 可以交换顺序，但 ⑦ 必须在这两者之后。</li></ul><h2 id="覆盖自检表-l3-01-→-l3-28-共-28-条-不漏不重" tabindex="-1">覆盖自检表（L3-01 → L3-28，共 28 条，不漏不重） <a class="header-anchor" href="#覆盖自检表-l3-01-→-l3-28-共-28-条-不漏不重" aria-label="Permalink to &quot;覆盖自检表（L3-01 → L3-28，共 28 条，不漏不重）&quot;">​</a></h2><blockquote><p>用法：学完一页勾一页；<strong>每个编号只归属一个页面，出现两次即为规划错误</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>编号</th><th>知识点</th><th>落在哪页</th><th>完成</th></tr></thead><tbody><tr><td>L3-01</td><td>RAG 是什么、解决什么问题</td><td><a href="./01-rag-fundamentals.html">① RAG 是什么</a></td><td>☐</td></tr><tr><td>L3-02</td><td>RAG 与微调、长上下文的取舍</td><td><a href="./01-rag-fundamentals.html">① RAG 是什么</a></td><td>☐</td></tr><tr><td>L3-03</td><td>四步构建最小 RAG</td><td><a href="./01-rag-fundamentals.html">① RAG 是什么</a></td><td>☐</td></tr><tr><td>L3-04</td><td>文档加载与多格式解析</td><td><a href="./02-loading-and-parsing.html">② 加载与解析</a></td><td>☐</td></tr><tr><td>L3-05</td><td>文本切块（Chunking）策略</td><td><a href="./03-chunking.html">③ 切块</a></td><td>☐</td></tr><tr><td>L3-06</td><td>切块参数与重叠窗口</td><td><a href="./03-chunking.html">③ 切块</a></td><td>☐</td></tr><tr><td>L3-07</td><td>元数据与结构化清洗</td><td><a href="./03-chunking.html">③ 切块</a></td><td>☐</td></tr><tr><td>L3-08</td><td>Embedding 模型原理与选型</td><td><a href="./04-embedding.html">④ Embedding</a></td><td>☐</td></tr><tr><td>L3-09</td><td>Embedding 维度、距离度量与归一化</td><td><a href="./04-embedding.html">④ Embedding</a></td><td>☐</td></tr><tr><td>L3-10</td><td>中文与多语言 Embedding 选型</td><td><a href="./04-embedding.html">④ Embedding</a></td><td>☐</td></tr><tr><td>L3-11</td><td>微调 Embedding 模型</td><td><a href="./04-embedding.html">④ Embedding</a></td><td>☐</td></tr><tr><td>L3-12</td><td>向量数据库与索引基础</td><td><a href="./05-vector-index.html">⑤ 向量索引</a></td><td>☐</td></tr><tr><td>L3-13</td><td>向量库选型与工程落地</td><td><a href="./05-vector-index.html">⑤ 向量索引</a></td><td>☐</td></tr><tr><td>L3-14</td><td>向量索引优化</td><td><a href="./05-vector-index.html">⑤ 向量索引</a></td><td>☐</td></tr><tr><td>L3-15</td><td>相似度检索 Top-k 与阈值</td><td><a href="./05-vector-index.html">⑤ 向量索引</a></td><td>☐</td></tr><tr><td>L3-16</td><td>BM25 与稀疏检索</td><td><a href="./06-sparse-and-hybrid.html">⑥ 稀疏与混合</a></td><td>☐</td></tr><tr><td>L3-17</td><td>混合检索与融合（RRF/加权）</td><td><a href="./06-sparse-and-hybrid.html">⑥ 稀疏与混合</a></td><td>☐</td></tr><tr><td>L3-18</td><td>Rerank 与 Cross-Encoder 重排</td><td><a href="./07-rerank-and-query.html">⑦ 精排与查询改写</a></td><td>☐</td></tr><tr><td>L3-19</td><td>查询改写与扩展（Query Rewriting / HyDE）</td><td><a href="./07-rerank-and-query.html">⑦ 精排与查询改写</a></td><td>☐</td></tr><tr><td>L3-20</td><td>查询重构与分发（多查询 / 路由）</td><td><a href="./07-rerank-and-query.html">⑦ 精排与查询改写</a></td><td>☐</td></tr><tr><td>L3-21</td><td>多跳检索与迭代检索</td><td><a href="./07-rerank-and-query.html">⑦ 精排与查询改写</a></td><td>☐</td></tr><tr><td>L3-22</td><td>Text2SQL 与结构化数据问答</td><td><a href="./08-structured-and-graph.html">⑧ 结构化、图谱与多模态</a></td><td>☐</td></tr><tr><td>L3-23</td><td>GraphRAG 与知识图谱增强检索</td><td><a href="./08-structured-and-graph.html">⑧ 结构化、图谱与多模态</a></td><td>☐</td></tr><tr><td>L3-24</td><td>多模态 RAG（图文检索）</td><td><a href="./08-structured-and-graph.html">⑧ 结构化、图谱与多模态</a></td><td>☐</td></tr><tr><td>L3-25</td><td>引用与可溯源性（Citations）</td><td><a href="./09-citations-and-security.html">⑨ 引用与权限</a></td><td>☐</td></tr><tr><td>L3-26</td><td>权限与多租户检索隔离</td><td><a href="./09-citations-and-security.html">⑨ 引用与权限</a></td><td>☐</td></tr><tr><td>L3-27</td><td>RAG 生成阶段的提示与约束</td><td><a href="./10-generation-and-agentic.html">⑩ 生成约束与 Agentic</a></td><td>☐</td></tr><tr><td>L3-28</td><td>Agentic RAG</td><td><a href="./10-generation-and-agentic.html">⑩ 生成约束与 Agentic</a></td><td>☐</td></tr></tbody></table><p><strong>合计校验</strong>：28 条 → ① 3 条｜② 1 条｜③ 3 条｜④ 4 条｜⑤ 4 条｜⑥ 2 条｜⑦ 4 条｜⑧ 3 条｜⑨ 2 条｜⑩ 2 条 = <strong>28</strong>，缺失 <strong>0</strong>，重复 <strong>0</strong>。学时 9+5+11+14+14+7+14+17+6+8 = <strong>101 h</strong>。</p><h2 id="必须能画出来的图-面试白板题" tabindex="-1">必须能画出来的图（面试白板题） <a class="header-anchor" href="#必须能画出来的图-面试白板题" aria-label="Permalink to &quot;必须能画出来的图（面试白板题）&quot;">​</a></h2><p>这七张图不是&quot;看着好看&quot;，而是<strong>面试官让你在白板上讲清楚系统时会直接画的东西</strong>。判断标准：能<strong>不看笔记从零画出来</strong>，并且每画一个节点都说得出它的输入输出与失败模式。</p><table tabindex="0"><thead><tr><th>#</th><th>图</th><th>要能画出的关键点</th><th>对应页面 / 图库</th></tr></thead><tbody><tr><td>1</td><td><strong>RAG 端到端（离线索引 + 在线问答两条链路）</strong></td><td>离线（解析→切块→向量化→入库）与在线（查询→检索→融合→精排→生成→引用）<strong>分开画</strong>，并标出两条链路在哪一步交汇</td><td><a href="./01-rag-fundamentals.html">①</a> ｜ <a href="/learn/diagrams/rag-pipeline.html">/diagrams/rag-pipeline</a></td></tr><tr><td>2</td><td><strong>解析到切块的数据流</strong></td><td>文档 → 版面还原 → 阅读顺序 → 清洗 → 切块 → 元数据，并标出<strong>每次转换丢失了什么</strong></td><td><a href="./02-loading-and-parsing.html">②</a> ｜ <a href="/learn/diagrams/rag-offline-indexing.html">/diagrams/rag-offline-indexing</a></td></tr><tr><td>3</td><td><strong>Embedding 与向量检索</strong></td><td>双塔各自编码 → 归一化 → 相似度 → ANN 索引（Flat 精确 / HNSW 图 / IVF 倒排 + PQ 压缩）</td><td><a href="./04-embedding.html">④</a> ｜ <a href="./05-vector-index.html">⑤</a></td></tr><tr><td>4</td><td><strong>混合检索 + Rerank</strong></td><td>稠密路与稀疏路<strong>并行</strong>取候选 → RRF 融合（按 rank 不是按分数）→ Cross-Encoder 精排 → 取 top-n 进上下文；标明两路各自的失败模式</td><td><a href="./06-sparse-and-hybrid.html">⑥</a> ｜ <a href="/learn/diagrams/hybrid-retrieval-rerank.html">/diagrams/hybrid-retrieval-rerank</a></td></tr><tr><td>5</td><td><strong>查询改写多路</strong></td><td>原查询 → 改写/扩展/HyDE → 多子查询并行检索 → 去重 + 融合；标出「一次额外 LLM 调用」的成本位置</td><td><a href="./07-rerank-and-query.html">⑦</a></td></tr><tr><td>6</td><td><strong>GraphRAG</strong></td><td>索引侧（实体关系抽取 → 建图 → 社区检测 → 社区摘要）与查询侧（局部：实体邻域多跳；全局：社区摘要聚合）<strong>分开画</strong></td><td><a href="./08-structured-and-graph.html">⑧</a></td></tr><tr><td>7</td><td><strong>多模态检索</strong></td><td>图 + 图注 + 引用段打包 → 与文本<strong>同一向量空间</strong>；以及&quot;OCR 文本化&quot;这条对照路线丢了什么</td><td><a href="./08-structured-and-graph.html">⑧</a></td></tr></tbody></table><blockquote><p>图库里已交付的检索类图：<a href="/learn/diagrams/rag-pipeline.html">RAG 端到端流程</a>、<a href="/learn/diagrams/rag-arch-overview.html">架构全景</a>、<a href="/learn/diagrams/rag-offline-indexing.html">离线索引</a>、<a href="/learn/diagrams/hybrid-retrieval-rerank.html">混合检索与重排</a>、<a href="/learn/diagrams/rag-chunking-pipeline.html">切块流水线</a>、<a href="/learn/diagrams/rag-dual-retrieval.html">双路召回</a>、<a href="/learn/diagrams/rag-request-latency.html">请求延迟构成</a>。全部：<a href="/learn/diagrams/">/diagrams/</a></p></blockquote><h2 id="这一层最容易挂在哪" tabindex="-1">这一层最容易挂在哪 <a class="header-anchor" href="#这一层最容易挂在哪" aria-label="Permalink to &quot;这一层最容易挂在哪&quot;">​</a></h2><p>按<strong>面试被问到的概率 × 答错的代价</strong>排序，五条：</p><p><strong>1）把 RRF 的 <code>k</code> 当成&quot;相似度阈值&quot;或&quot;权重&quot;（⑥ L3-17）。</strong> <code>k</code> 是<strong>排名偏移量</strong>，取最小排名加上一个平滑常数，作用是<strong>压掉头部名次的过大优势</strong>、让后面的名次也有机会贡献——它<strong>不是分数</strong>，也不是&quot;调大了就更严格&quot;。连带的高频错误是<strong>把 RRF 融合分（本项目实测区间约 0.016–0.033）当成精排分去比 0.30 阈值</strong>，结果每一道题都被拒答。<strong>判据：先问这个分数的性质，再谈阈值。</strong></p><p><strong>2）把 <code>Recall@10 == Recall@5</code> 当成&quot;检索已经到顶&quot;（⑤ L3-15）。</strong> 这个相等<strong>是标注窗口造成的构造性结果</strong>——机器 gt 的候选只取 <code>retrieve()[:5]</code>，人只看前 5 个，所以 R@10 在定义上就追平了 R@5。修正后暴露的真实情况是：<strong>不做精排时 R@10 比 R@5 高 11–14 个百分点</strong>。这题考的是&quot;你会不会怀疑自己的指标口径&quot;，答&quot;说明前 5 条已经够了&quot;就是踩进去了。</p><p><strong>3）认为&quot;同语言 = 同主题&quot;，用 BM25 兜跨语种（⑥ L3-16）。</strong> 扩库后中文查询的 BM25 top-20 <strong>全部来自那两篇中文文献</strong>（两路零重叠），混合检索 R@5 从 <strong>64.5% 崩到 29.2%</strong>。根因是中文分词产出的词元在语料里 <code>df=0</code>，被 BM25 当成&quot;极高区分度词&quot;。修法是加<strong>准入自检</strong>（两路交集过小就丢弃稀疏路，<code>SPARSE_MODE=overlap</code>）——但这只是<strong>止血</strong>，跨语种真正要做的是<strong>语义桥</strong>（查询翻译），实测 R@5 从 8.3% → 29.2%（术语表）→ <strong>70.8%</strong>（查询翻译）。</p><p><strong>4）给 chunk size、top_k、<code>M</code>/<code>efConstruction</code> 报&quot;最佳值&quot;（③④⑤）。</strong> 这一层的正确答案永远是<strong>判据 + 消融方法</strong>：chunk size 看语义完整性、检索单元粒度、上下文预算三条；<code>M</code>/<code>efConstruction</code>、<code>nprobe</code>/<code>ef</code> 看召回-延迟曲线的拐点；top_k 要<strong>分三处（召回 / 融合 / 进上下文）分别定</strong>。报一个具体数字并说&quot;业界最佳&quot;，是这一层最快的失分方式。</p><p><strong>5）把&quot;我没做过的&quot;说成&quot;我做过&quot;（全层，尤其 ⑧ 与 ⑩）。</strong> 本项目<strong>没有实现</strong> Text2SQL、GraphRAG、多模态检索、查询改写（含 HyDE）、多查询、路由、多跳检索、Agentic RAG、多租户隔离。这些题的正确答法是：<strong>说清它解决什么问题、代价是什么、我为什么现在不做、要做的话第一步是什么</strong>——比如&quot;先补评测题类（多跳题 / 免检索题 / 全局性问题 / 图文题现在都是空的），否则做完无法判断有没有变好&quot;。<strong>&quot;我知道瓶颈在哪、该往哪修，但我没修&quot;比编一个优化后的数字安全得多。</strong></p><blockquote><p>补充两条&quot;隐形的坑&quot;，不一定被直接问到，但会决定你答得深不深：<strong>① 误拒率是一个统计量而不是一组固定坏样本</strong>（23 道可回答题每轮固定 3 道被误拒，但中招的题每轮不同）——盯单题找根因找不到；<strong>② 精排 8.5 s（CPU）与 LLM 生成 1.26 s 的对比告诉你瓶颈在哪</strong>：端到端 P50 15.66 s 里检索占约 92%，所以&quot;优化 LLM&quot;是错误方向，而&quot;先返回来源列表再流式出答案&quot;这类<strong>把等待变可见</strong>的产品层改动，收益比模型层大。</p></blockquote><hr><p><strong>本层与项目的对应</strong>：这一层讲的几乎每个环节，都能在你的科研文献 RAG 项目里找到真实痕迹——语料 <strong>55 篇 / 5325 块</strong>，切块三档（<code>&quot;512&quot;</code> 档实际 <code>max_chars</code> <strong>1024</strong> 字符 / <code>overlap_chars</code> <strong>153</strong>，<code>&quot;1024&quot;</code> 档 <strong>2048 / 307</strong>），检索三档实测 <strong>① 纯向量 R@5 64.4% ｜ ② 混合无精排 59.1% ｜ ③ 混合+精排 71.8%</strong>，双层拒答（程序层阈值 <strong>0.30</strong> + 模型层自述），<code>RRF_K = 60</code>、<code>RERANK_TOP_N = 5</code>、三个 <code>TOP_K</code> 均为 <strong>20</strong>、<code>LLM_TEMPERATURE = 0.1</code>。逐条出处见各页末尾的 <code>&lt;!-- 事实来源 --&gt;</code> 注释。</p><ul><li>项目实例：<a href="/learn/projects/rag/01-positioning.html">科研文献 RAG 问答</a> ｜ <a href="/learn/projects/rag/02-indexing.html">离线索引流水线</a></li><li>上层关联：<a href="/learn/kb/l2-prompt/">L2 · 提示工程与结构化输出</a> ｜ 下一层：<a href="/learn/kb/l4-agent/">L4 · Agent</a></li><li>面试专项：<a href="/learn/interview/rag.html">/interview/rag</a> ｜ <a href="/learn/interview/cheatsheet.html">/interview/cheatsheet</a></li><li>图库：<a href="/learn/diagrams/">/diagrams/</a></li></ul>',30)])])}const u=d(n,[["render",o]]);export{m as __pageData,u as default};
